// Port-validation application interface (board independent).
// Handwritten for qp-arduino (QP/C++ v7.3.4). Not generated by QM.
#ifndef VALIDATION_HPP
#define VALIDATION_HPP

enum ValidationSignals {
    TIMEOUT_SIG = QP::Q_USER_SIG,
    VALIDATE_SIG,
    DYN_SIG,
    MAX_PUB_SIG
};

enum ValidationRecords { // application-specific QS records
    VALIDATION_STAT = QP::QS_USER,
    PROBE_ROLE
};

struct ValidationEvt : public QP::QEvt {
    std::uint32_t seq;
};

extern QP::QActive * const AO_Validator;
void Validator_report();        // emit VALIDATION_STAT now
void Validator_resetCounters();

#endif // VALIDATION_HPP
